// UI/UX-дизайнер · розділи й рівні.
//   pair   — два варіанти інтерфейсу: вибрати зручніший (ok: 'a' | 'b'); marks — що не так у гіршому
//   spot   — один макет: клацнути на проблемне місце (bad — назва частини)
//   choice — запитання з варіантами (mock — необов’язковий макет над ним)
//   fix    — виправити самому: перемикачі змінюють макет, перевірки оновлюються одразу
import { contrast } from './logic.js';

export const CHAPTERS = [
  { id: 'read', name: 'Контраст і читання', desc: 'Щоб текст було легко прочитати' },
  { id: 'space', name: 'Відступи й вирівнювання', desc: 'Повітря, близькість і рівні лінії' },
  { id: 'hier', name: 'Ієрархія й акценти', desc: 'Головне — помітно, другорядне — тихіше' },
  { id: 'forms', name: 'Кнопки й форми', desc: 'Зрозуміло, що натискати й що вводити' },
  { id: 'master', name: 'Майстерня дизайнера', desc: 'Знаходимо й виправляємо все разом' },
];

const o = (t, ok, why) => ({ t, ok, why });
const pair = (q, a, b, ok, why, marks) => ({ kind: 'pair', q, a, b, ok, why, marks });
const spot = (q, mock, bad, why) => ({ kind: 'spot', q, mock, bad, why });
const choice = (q, options, mock) => ({ kind: 'choice', q, options, mock });

/* ── Макети, з яких складаються завдання ── */
const TXT = 'Наступного тижня 7-А клас їде на екскурсію до планетарію. Ми побачимо зоряне небо, дізнаємося, як народжуються зірки, і сфотографуємося біля справжнього метеорита.';
